# Check if song 40 is in the downloaded songs list
downloaded_ids = {song['song_id'] for song in downloaded}
print("Song 40 downloaded?", 40 in downloaded_ids)

# Continue moving to next songs until we find one that is downloaded
downloaded_ids = {song['song_id'] for song in downloaded}
max_steps = 50
for i in range(max_steps):
    result = apis.spotify.next_song(access_token=access_token)
    song_id = result['song_id']
    print(f"Step {i+1}: moved to song_id={song_id}")
    if song_id in downloaded_ids:
        print(f"Found downloaded song: {song_id}")
        break
else:
    print("No downloaded song found within limit")

# Fetch all downloaded songs (paginate)
downloaded_songs = []
page_index = 0
while True:
    page = apis.spotify.show_downloaded_songs(access_token=access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    downloaded_songs.extend(page)
    if len(page) < 20:
        break
    page_index += 1

downloaded_ids = {song['song_id'] for song in downloaded_songs}
print("Downloaded song IDs:", downloaded_ids)

