# Identify songs to archive and remove from playlists
old_titles_set = set(old_song_titles)
added_song_ids = set()
songs_to_archive = []  # list of (playlist_id, song_id, title)

for pl in playlist_details:
    for song in pl['songs']:
        if song['title'] in old_titles_set:
            songs_to_archive.append((pl['playlist_id'], song['id'], song['title']))
            if song['id'] not in added_song_ids:
                added_song_ids.add(song['id'])

print(f"Songs to remove: {len(songs_to_archive)}")
print(f"Unique songs to add: {len(added_song_ids)}")
for pid, sid, title in songs_to_archive:
    print(f"Playlist {pid}: song {sid} - {title}")

