    for sid in to_remove:
        # Remove from original playlist
        apis.spotify.remove_song_from_playlist(playlist_id=pid, song_id=sid, access_token=spotify_token)
        # Add to archived playlist, but ignore if already present
        try:
            apis.spotify.add_song_to_playlist(playlist_id=new_playlist_id, song_id=sid, access_token=spotify_token)
            print(f"Removed song {sid} from playlist {pid} and added to archived")
        except Exception as e:
            if "already in the playlist" in str(e):
                print(f"Song {sid} already in archived, skipped adding")
            else:
                raise

