steps.code:
# Let's search for each song in songs_to_archive to get their song IDs
song_id_map = {}  # key: (title, artist) -> song_id
for song in songs_to_archive:
    title = song['title']
    artist = song['artist']
    query = f"{title} {artist}"
    results = apis.spotify.search_songs(query=query, access_token=spotify_token, page_limit=20)
    # results is a list of songs
    found = None
    for s in results:
        # Check if title matches and artist matches
        if s['title'].lower() == title.lower():
            # Check if any artist matches
            for a in s['artists']:
                if a['name'].lower() == artist.lower():
                    found = s
                    break
            if found:
                break
    if found:
        song_id_map[(title, artist)] = found['song_id']
        print(f"Found: {title} by {artist} -> song_id={found['song_id']}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print(f"\nTotal songs mapped: {len(song_id_map)}")

