# Parse the old songs list from the file content
old_songs = []
for line in file_data['content'].splitlines():
    line = line.strip()
    if line.startswith('- '):
        song_part = line[2:]
        if ' by ' in song_part:
            title, artist = song_part.rsplit(' by ', 1)
            old_songs.append({'title': title.strip(), 'artist': artist.strip()})
print(old_songs)

