# Process all TODO songs to find their release months
release_info = {}
for song in todo_songs:
    found = find_song_release(song['title'], song['artists'])
    if found:
        release_date = found['release_date']
        # Extract month and year
        dt = datetime.fromisoformat(release_date)
        month_year = f"{dt.month:02d}/{dt.year}"
        release_info[song['title']] = month_year
        print(f"{song['title']} -> {month_year}")
    else:
        print(f"NOT FOUND: {song['title']}")

# Now update the note content with the release months
new_lines = []
for line in lines:
    if 'RELEASED_AT TODO' in line:
        m = re.match(r'- (.+?) BY (.+?) RELEASED_AT TODO', line)
        if m:
            title = m.group(1).strip()
            if title in release_info:
                new_line = line.replace('RELEASED_AT TODO', f'RELEASED_AT {release_info[title]}')
                new_lines.append(new_line)
                print(f"Replaced: {new_line}")
            else:
                new_lines.append(line)
        else:
            new_lines.append(line)
    else:
        new_lines.append(line)

new_content = '\n'.join(new_lines)
print("\n--- New content ---")
print(new_content)

