            artists = ', '.join(a['name'] for a in s['artists'])
            print(f"  ID={s['song_id']} Title='{s['title']}' Artists='{artists}' Release={s['release_date']}")
    else:
        print("  No results")

# Update the note content by replacing TODO with release month/year
new_lines = []
for line in content.strip().split('\n'):
    if line.startswith('- '):
        m = re.match(r'- (.+?) BY (.+?) RELEASED_AT (.+)', line)
        if m:
            title = m.group(1).strip()
            artists = m.group(2).strip()
            release = m.group(3).strip()
            if release == 'TODO' and title in title_to_release:
                new_release = title_to_release[title]
                new_line = f"- {title} BY {artists} RELEASED_AT {new_release}"
                new_lines.append(new_line)
            else:
                new_lines.append(line)
        else:
            new_lines.append(line)
    else:
        new_lines.append(line)

new_content = '\n'.join(new_lines)
print(new_content)

