steps.code:
# Parse the note content to extract songs with TODO
content_lines = note['content'].split('\n')
songs_todo = []
for line in content_lines:
    if line.startswith('- '):
        # Extract title, artists, and release info
        # Format: - Title BY Artist1, Artist2 RELEASED_AT MM/YYYY or TODO
        parts = line[2:].split(' BY ')
        if len(parts) == 2:
            title = parts[0].strip()
            rest = parts[1].split(' RELEASED_AT ')
            if len(rest) == 2:
                artists_str = rest[0].strip()
                release = rest[1].strip()
                if release == 'TODO':
                    artists = [a.strip() for a in artists_str.split(',')]
                    songs_todo.append({'title': title, 'artists': artists, 'line': line})
print(f"Found {len(songs_todo)} songs with TODO")
for s in songs_todo:
    print(s)

