steps.code:
# Let's find release dates for all TODO songs
release_info = {}
for song in songs_todo:
    result = apis.spotify.search_songs(query=song['title'], access_token=spotify_token, page_limit=20)
    matches = []
    for s in result:
        if s['title'].lower() == song['title'].lower():
            song_artists = [a['name'] for a in s['artists']]
            if all(artist in song_artists for artist in song['artists']):
                matches.append(s)
    if len(matches) == 1:
        release_date = matches[0]['release_date']
        # Extract month/year
        from datetime import datetime
        dt = datetime.fromisoformat(release_date)
        month_year = f"{dt.month:02d}/{dt.year}"
        release_info[song['title']] = month_year
        print(f"{song['title']} -> {month_year}")
    else:
        print(f"WARNING: {len(matches)} matches for {song['title']}")

