steps.code:
# Build new content with release dates
new_lines = []
for line in content.split('\n'):
    if 'RELEASED_AT TODO' in line:
        m = re.match(r'- (.+?) BY (.+?) RELEASED_AT TODO', line)
        if m:
            title = m.group(1).strip()
            if title in release_dates:
                new_line = line.replace('RELEASED_AT TODO', f'RELEASED_AT {release_dates[title]}')
                new_lines.append(new_line)
            else:
                new_lines.append(line)  # keep as is if not found
        else:
            new_lines.append(line)
    else:
        new_lines.append(line)

new_content = '\n'.join(new_lines)
print(new_content)

